diff --git a/src/hostedrunner.cpp b/src/hostedrunner.cpp
new file mode 100644
index 0000000..88b6e6b
--- /dev/null
+++ b/src/hostedrunner.cpp
@@ -0,0 +1,102 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+#include "hostedrunner_p.h"
+
+#include <QCoreApplication>
+#include <QDBusConnection>
+#include <QDBusServiceWatcher>
+#include <QJsonObject>
+#include <QProcess>
+
+#include "krunner_debug.h"
+
+namespace KRunner
+{
+// Give up on a plugin that keeps crashing its host, instead of restarting it for every query session
+static constexpr int s_maxHostCrashes = 3;
+
+KPluginMetaData HostedRunner::hostMetaData(const KPluginMetaData &pluginMetaData)
+{
+    static int instance = 0;
+    QString pluginId = pluginMetaData.pluginId();
+    for (QChar &c : pluginId) {
+        if (!c.isLetterOrNumber() || c.unicode() > 127) {
+            c = QLatin1Char('_');
+        }
+    }
+    const QString service = QStringLiteral("org.kde.KRunnerHost.p%1.r%2_%3").arg(QCoreApplication::applicationPid()).arg(pluginId).arg(++instance);
+
+    QJsonObject json = pluginMetaData.rawData();
+    json.insert(QStringLiteral("X-Plasma-API"), QStringLiteral("DBus2"));
+    json.insert(QStringLiteral("X-Plasma-DBusRunner-Service"), service);
+    json.insert(QStringLiteral("X-Plasma-DBusRunner-Path"), QStringLiteral("/runner"));
+    return KPluginMetaData(json, pluginMetaData.fileName());
+}
+
+HostedRunner::HostedRunner(QObject *parent, const KPluginMetaData &pluginMetaData)
+    : DBusRunner(parent, hostMetaData(pluginMetaData))
+    , m_service(metadata().value(QStringLiteral("X-Plasma-DBusRunner-Service")))
+    , m_pluginFile(pluginMetaData.fileName())
+{
+    m_process = new QProcess(this);
+    m_process->setProcessChannelMode(QProcess::ForwardedChannels);
+    connect(m_process, &QProcess::finished, this, [this](int exitCode, QProcess::ExitStatus exitStatus) {
+        if (exitStatus == QProcess::CrashExit || exitCode != 0) {
+            ++m_crashCount;
+            qCWarning(KRUNNER) << "The process running" << id() << "exited unexpectedly" << exitCode << exitStatus;
+        }
+        // Wait for the restarted host before matching again
+        suspendMatching(true);
+        m_configPending = true;
+    });
+
+    auto watcher = new QDBusServiceWatcher(m_service, QDBusConnection::sessionBus(), QDBusServiceWatcher::WatchForOwnerChange, this);
+    connect(watcher, &QDBusServiceWatcher::serviceRegistered, this, [this] {
+        m_registered = true;
+        if (m_configPending) {
+            m_configPending = false;
+            DBusRunner::reloadConfiguration();
+        }
+    });
+    connect(watcher, &QDBusServiceWatcher::serviceUnregistered, this, [this] {
+        m_registered = false;
+    });
+
+    connect(this, &AbstractRunner::prepare, this, [this] {
+        if (m_process->state() == QProcess::NotRunning && m_crashCount < s_maxHostCrashes) {
+            startHost();
+        }
+    });
+
+    startHost();
+}
+
+HostedRunner::~HostedRunner()
+{
+    m_process->disconnect(this);
+    delete m_process;
+}
+
+void HostedRunner::startHost()
+{
+    m_configPending = true;
+    suspendMatching(true);
+    m_process->start(QStringLiteral(KRUNNER_RUNNERHOST), {m_pluginFile, m_service, QDBusConnection::sessionBus().baseService()});
+}
+
+void HostedRunner::reloadConfiguration()
+{
+    if (m_registered) {
+        DBusRunner::reloadConfiguration();
+    } else {
+        m_configPending = true;
+        suspendMatching(true);
+    }
+}
+}
+
+#include "moc_hostedrunner_p.cpp"
