diff --git a/src/runnercrashguard.cpp b/src/runnercrashguard.cpp
new file mode 100644
index 0000000..e35954a
--- /dev/null
+++ b/src/runnercrashguard.cpp
@@ -0,0 +1,207 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+#include "runnercrashguard_p.h"
+
+#include <QCoreApplication>
+#include <QDir>
+#include <QFileInfo>
+#include <QStandardPaths>
+
+#include <KConfigGroup>
+#include <KPluginMetaData>
+#include <KSharedConfig>
+
+#include <cstring>
+#include <iterator>
+
+#ifdef Q_OS_UNIX
+#include <cerrno>
+#include <signal.h>
+#endif
+
+#include "krunner_debug.h"
+
+namespace KRunner
+{
+Q_GLOBAL_STATIC(RunnerCrashGuard, s_crashGuard)
+
+// The runner the current thread is busy with
+static thread_local RunnerCrashGuard::Slot *t_currentSlot = nullptr;
+
+#ifdef Q_OS_UNIX
+static constexpr int s_crashSignals[] = {SIGSEGV, SIGBUS, SIGFPE, SIGILL, SIGABRT};
+static struct sigaction s_previousActions[std::size(s_crashSignals)];
+
+static void crashHandler(int signal, siginfo_t *info, void *context)
+{
+    if (t_currentSlot) {
+        t_currentSlot->crashed = 1;
+    }
+    // Hand over to whoever handled crashes before us, e.g. KCrash
+    for (size_t i = 0; i < std::size(s_crashSignals); ++i) {
+        if (s_crashSignals[i] != signal) {
+            continue;
+        }
+        const struct sigaction &previous = s_previousActions[i];
+        sigaction(signal, &previous, nullptr);
+        if (previous.sa_flags & SA_SIGINFO) {
+            previous.sa_sigaction(signal, info, context);
+        } else if (previous.sa_handler != SIG_DFL && previous.sa_handler != SIG_IGN) {
+            previous.sa_handler(signal);
+        } else {
+            raise(signal);
+        }
+        return;
+    }
+}
+#endif
+
+static KConfigGroup outOfProcessGroup()
+{
+    return KSharedConfig::openStateConfig(QStringLiteral("krunnerstaterc"))->group(QStringLiteral("OutOfProcessRunners"));
+}
+
+static qint64 pluginFileTimestamp(const QString &fileName)
+{
+    return QFileInfo(fileName).lastModified().toSecsSinceEpoch();
+}
+
+RunnerCrashGuard *RunnerCrashGuard::self()
+{
+    return s_crashGuard();
+}
+
+RunnerCrashGuard::RunnerCrashGuard()
+{
+#ifdef Q_OS_UNIX
+    const QString directory = QStandardPaths::writableLocation(QStandardPaths::GenericStateLocation) + QLatin1String("/krunner");
+    if (!QDir().mkpath(directory)) {
+        return;
+    }
+    collectCrashedRunners(directory);
+
+    m_file.setFileName(directory + QLatin1String("/crashguard-") + QString::number(QCoreApplication::applicationPid()));
+    const qint64 size = qint64(sizeof(Slot)) * s_slotCount;
+    if (!m_file.open(QIODevice::ReadWrite | QIODevice::Truncate) || !m_file.resize(size)) {
+        qCWarning(KRUNNER) << "Could not create" << m_file.fileName() << m_file.errorString();
+        return;
+    }
+    m_slots = reinterpret_cast<Slot *>(m_file.map(0, size));
+    if (!m_slots) {
+        return;
+    }
+    std::memset(static_cast<void *>(m_slots), 0, size);
+
+    struct sigaction action = {};
+    action.sa_sigaction = crashHandler;
+    action.sa_flags = SA_SIGINFO | SA_ONSTACK;
+    sigemptyset(&action.sa_mask);
+    for (size_t i = 0; i < std::size(s_crashSignals); ++i) {
+        sigaction(s_crashSignals[i], &action, &s_previousActions[i]);
+    }
+#endif
+}
+
+RunnerCrashGuard::~RunnerCrashGuard()
+{
+#ifdef Q_OS_UNIX
+    if (m_slots) {
+        for (size_t i = 0; i < std::size(s_crashSignals); ++i) {
+            sigaction(s_crashSignals[i], &s_previousActions[i], nullptr);
+        }
+    }
+#endif
+    // A normal exit
+    if (m_file.isOpen()) {
+        QFile::remove(m_file.fileName());
+    }
+}
+
+void RunnerCrashGuard::collectCrashedRunners(const QString &directory)
+{
+#ifdef Q_OS_UNIX
+    const QDir dir(directory);
+    const QStringList files = dir.entryList({QStringLiteral("crashguard-*")}, QDir::Files);
+    for (const QString &fileName : files) {
+        bool ok = false;
+        const qint64 pid = QStringView(fileName).mid(11).toLongLong(&ok);
+        if (!ok || pid == QCoreApplication::applicationPid() || kill(pid, 0) == 0 || errno != ESRCH) {
+            continue;
+        }
+
+        QFile file(dir.filePath(fileName));
+        if (file.open(QIODevice::ReadOnly)) {
+            const QByteArray data = file.readAll();
+            const auto slotData = reinterpret_cast<const Slot *>(data.constData());
+            const qsizetype count = data.size() / qsizetype(sizeof(Slot));
+            for (qsizetype i = 0; i < count; ++i) {
+                if (!slotData[i].crashed) {
+                    continue;
+                }
+                const QString pluginId = QString::fromUtf8(slotData[i].pluginId, qstrnlen(slotData[i].pluginId, sizeof(Slot::pluginId)));
+                const KPluginMetaData metaData = KPluginMetaData::findPluginById(QStringLiteral("kf6/krunner"), pluginId);
+                if (metaData.isValid()) {
+                    qCWarning(KRUNNER) << "Runner" << pluginId << "crashed process" << pid << "- it will be run in a separate process from now on";
+                    outOfProcessGroup().writeEntry(pluginId, pluginFileTimestamp(metaData.fileName()));
+                }
+            }
+        }
+        file.remove();
+    }
+    outOfProcessGroup().sync();
+#else
+    Q_UNUSED(directory)
+#endif
+}
+
+bool RunnerCrashGuard::shouldRunOutOfProcess(const KPluginMetaData &pluginMetaData) const
+{
+    KConfigGroup group = outOfProcessGroup();
+    if (!group.hasKey(pluginMetaData.pluginId())) {
+        return false;
+    }
+    // Give updated plugins another chance
+    if (group.readEntry(pluginMetaData.pluginId(), qint64(0)) != pluginFileTimestamp(pluginMetaData.fileName())) {
+        group.deleteEntry(pluginMetaData.pluginId());
+        group.sync();
+        return false;
+    }
+    return true;
+}
+
+RunnerCrashGuard::Slot *RunnerCrashGuard::slotFor(const QString &pluginId)
+{
+    if (!m_slots) {
+        return nullptr;
+    }
+    QMutexLocker locker(&m_mutex);
+    if (auto it = m_slotIndexes.constFind(pluginId); it != m_slotIndexes.cend()) {
+        return &m_slots[*it];
+    }
+    const QByteArray id = pluginId.toUtf8();
+    if (m_slotIndexes.size() >= s_slotCount || id.size() >= qsizetype(sizeof(Slot::pluginId))) {
+        return nullptr;
+    }
+    const int index = m_slotIndexes.size();
+    std::memcpy(m_slots[index].pluginId, id.constData(), id.size());
+    m_slotIndexes.insert(pluginId, index);
+    return &m_slots[index];
+}
+
+RunnerCrashGuard::Scope::Scope(const QString &pluginId)
+    : m_previousSlot(t_currentSlot)
+{
+    if (auto guard = RunnerCrashGuard::self()) {
+        t_currentSlot = guard->slotFor(pluginId);
+    }
+}
+
+RunnerCrashGuard::Scope::~Scope()
+{
+    t_currentSlot = m_previousSlot;
+}
+}
