+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <QFile>
+#include <QHash>
+#include <QMutex>
+#include <QString>
+
+class KPluginMetaData;
+
+namespace KRunner
+{
+/*
+ * Remembers which C++ runner was being loaded, was matching or was running a match in the thread
+ * that crashed the process, in a small memory mapped file per process. The next process that loads
+ * runners finds the file of the dead process and remembers that runner, so that it gets loaded
+ * out of process from then on, until its plugin file changes.
+ */
+class RunnerCrashGuard
+{
+public:
+    struct Slot {
+        char pluginId[124];
+        qint32 crashed;
+    };
+
+    static RunnerCrashGuard *self();
+
+    RunnerCrashGuard();
+    ~RunnerCrashGuard();
+
+    bool shouldRunOutOfProcess(const KPluginMetaData &pluginMetaData) const;
+
+    class Scope
+    {
+    public:
+        explicit Scope(const QString &pluginId);
+        ~Scope();
+        Q_DISABLE_COPY_MOVE(Scope)
+
+    private:
+        Slot *const m_previousSlot;
+    };
+
+private:
+    static constexpr int s_slotCount = 128;
+
+    void collectCrashedRunners(const QString &directory);
+    Slot *slotFor(const QString &pluginId);
+
+    QFile m_file;
+    Slot *m_slots = nullptr;
+    QMutex m_mutex;
+    QHash<QString, int> m_slotIndexes;
+};
+}
