@@ -0,0 +1,225 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+// Runs a single C++ runner plugin and offers it on the session bus with the org.kde.krunner1 interface
+
+#include <QDBusConnection>
+#include <QDBusConnectionInterface>
+#include <QDBusContext>
+#include <QDBusMessage>
+#include <QDBusMetaType>
+#include <QDBusServiceWatcher>
+#include <QGuiApplication>
+#include <QIcon>
+#include <QImage>
+#include <QSet>
+#include <QThread>
+
+#include <KConfig>
+#include <KConfigGroup>
+#include <KPluginFactory>
+#include <KPluginMetaData>
+#include <KRunner/AbstractRunner>
+#include <KRunner/QueryMatch>
+#include <KRunner/RunnerContext>
+#include <KRunner/RunnerManager>
+#include <KWindowSystem>
+
+#include <atomic>
+
+#include "../dbusutils_p.h"
+
+class RunnerHost : public QObject, protected QDBusContext
+{
+    Q_OBJECT
+    Q_CLASSINFO("D-Bus Interface", "org.kde.krunner1")
+
+public:
+    explicit RunnerHost(KRunner::AbstractRunner *runner)
+        : m_runner(runner)
+        , m_config(QString(), KConfig::SimpleConfig)
+        , m_manager(m_config.group(QStringLiteral("Plugins")), m_config.group(QStringLiteral("State")), this)
+    {
+    }
+
+public Q_SLOTS:
+    KRunner::Actions Actions()
+    {
+        return {};
+    }
+
+    QVariantMap Config()
+    {
+        QVariantMap config;
+        QMetaObject::invokeMethod(m_runner, "reloadConfigurationInternal", Qt::BlockingQueuedConnection);
+        config.insert(QStringLiteral("MinLetterCount"), m_runner->minLetterCount());
+        if (m_runner->hasMatchRegex()) {
+            config.insert(QStringLiteral("MatchRegex"), m_runner->matchRegex().pattern());
+        }
+        return config;
+    }
+
+    RemoteMatches Match(const QString &query)
+    {
+        if (!m_prepared) {
+            m_prepared = true;
+            Q_EMIT m_runner->prepare();
+        }
+
+        setDelayedReply(true);
+        const QDBusMessage message = this->message();
+        const int queryNumber = ++m_lastQuery;
+        QMetaObject::invokeMethod(m_runner, [this, message, query, queryNumber] {
+            KRunner::RunnerContext context;
+            context.setQuery(query);
+            // A newer query is already waiting, like RunnerManager this one does not need to be finished
+            if (queryNumber == m_lastQuery && !m_runner->isMatchingSuspended()) {
+                m_runner->match(context);
+            }
+            const QList<KRunner::QueryMatch> matches = context.matches();
+            QMetaObject::invokeMethod(this, [this, message, matches] {
+                QDBusConnection::sessionBus().send(message.createReply(QVariant::fromValue(convertMatches(matches))));
+            });
+        });
+        return {};
+    }
+
+    void Run(const QString &matchId, const QString &actionId)
+    {
+        const auto it = m_matches.constFind(matchId);
+        if (it == m_matches.cend()) {
+            return;
+        }
+        const KRunner::QueryMatch &match = it.value();
+        KRunner::Action selectedAction;
+        const auto actions = match.actions();
+        for (const KRunner::Action &action : actions) {
+            if (action.id() == actionId) {
+                selectedAction = action;
+            }
+        }
+        m_manager.run(match, selectedAction);
+    }
+
+    void SetActivationToken(const QString &token)
+    {
+        KWindowSystem::setCurrentXdgActivationToken(token);
+    }
+
+    void Teardown()
+    {
+        m_matches.clear();
+        if (m_prepared) {
+            m_prepared = false;
+            Q_EMIT m_runner->teardown();
+        }
+    }
+
+private:
+    RemoteMatches convertMatches(const QList<KRunner::QueryMatch> &matches)
+    {
+        RemoteMatches remoteMatches;
+        QSet<QString> ids;
+        const QString idPrefix = m_runner->id() + QLatin1Char('_');
+        for (const KRunner::QueryMatch &match : matches) {
+            RemoteMatch remoteMatch;
+            // The calling side adds the runner id again
+            remoteMatch.id = match.id().startsWith(idPrefix) ? match.id().mid(idPrefix.size()) : match.id();
+            if (remoteMatch.id.isEmpty() || ids.contains(remoteMatch.id)) {
+                remoteMatch.id += QLatin1Char('#') + QString::number(++m_lastId);
+            }
+            ids.insert(remoteMatch.id);
+            m_matches.insert(remoteMatch.id, match);
+
+            remoteMatch.text = match.text();
+            remoteMatch.iconName = match.iconName();
+            remoteMatch.categoryRelevance = match.categoryRelevance();
+            remoteMatch.relevance = match.relevance();
+            remoteMatch.properties.insert(QStringLiteral("urls"), QUrl::toStringList(match.urls()));
+            remoteMatch.properties.insert(QStringLiteral("category"), match.matchCategory());
+            remoteMatch.properties.insert(QStringLiteral("subtext"), match.subtext());
+            remoteMatch.properties.insert(QStringLiteral("multiline"), match.isMultiLine());
+            remoteMatch.properties.insert(QStringLiteral("actions"), QVariant::fromValue(match.actions()));
+            if (remoteMatch.iconName.isEmpty() && !match.icon().isNull()) {
+                const QImage image = match.icon().pixmap(64).toImage().convertToFormat(QImage::Format_RGBA8888);
+                RemoteImage remoteImage;
+                remoteImage.width = image.width();
+                remoteImage.height = image.height();
+                remoteImage.rowStride = image.bytesPerLine();
+                remoteImage.hasAlpha = true;
+                remoteImage.bitsPerSample = 8;
+                remoteImage.channels = 4;
+                remoteImage.data = QByteArray(reinterpret_cast<const char *>(image.constBits()), image.sizeInBytes());
+                remoteMatch.properties.insert(QStringLiteral("icon-data"), QVariant::fromValue(remoteImage));
+            }
+            remoteMatches << remoteMatch;
+        }
+        return remoteMatches;
+    }
+
+    KRunner::AbstractRunner *const m_runner;
+    KConfig m_config;
+    // Only used to run matches, like the calling side would
+    KRunner::RunnerManager m_manager;
+    QHash<QString, KRunner::QueryMatch> m_matches;
+    std::atomic<int> m_lastQuery = 0;
+    quint64 m_lastId = 0;
+    bool m_prepared = false;
+};
