+int main(int argc, char **argv)
+{
+    QGuiApplication app(argc, argv);
+    QGuiApplication::setQuitOnLastWindowClosed(false);
+
+    const QStringList arguments = app.arguments();
+    if (arguments.size() != 4) {
+        qWarning("Usage: %s <runner plugin file> <service name> <service to quit with>", qPrintable(arguments.constFirst()));
+        return 1;
+    }
+
+    qDBusRegisterMetaType<RemoteMatch>();
+    qDBusRegisterMetaType<RemoteMatches>();
+    qDBusRegisterMetaType<KRunner::Action>();
+    qDBusRegisterMetaType<KRunner::Actions>();
+    qDBusRegisterMetaType<RemoteImage>();
+
+    QObject runnerParent;
+    auto result = KPluginFactory::instantiatePlugin<KRunner::AbstractRunner>(KPluginMetaData(arguments.at(1)), &runnerParent);
+    if (!result) {
+        qWarning() << "Could not load runner" << arguments.at(1) << result.errorString;
+        return 1;
+    }
+    KRunner::AbstractRunner *runner = result.plugin;
+
+    // Like RunnerManager does, so that the runner is initialized and matches in its own thread
+    QThread thread;
+    thread.setObjectName(runner->id());
+    thread.start();
+    runner->moveToThread(&thread);
+    QMetaObject::invokeMethod(runner, [] { }, Qt::BlockingQueuedConnection);
+    QObject::connect(&app, &QCoreApplication::aboutToQuit, &thread, [&thread] {
+        thread.quit();
+        thread.wait();
+    });
+
+    QDBusServiceWatcher parentWatcher(arguments.at(3), QDBusConnection::sessionBus(), QDBusServiceWatcher::WatchForUnregistration);
+    QObject::connect(&parentWatcher, &QDBusServiceWatcher::serviceUnregistered, &app, &QCoreApplication::quit);
+    if (!QDBusConnection::sessionBus().interface()->isServiceRegistered(arguments.at(3))) {
+        return 0;
+    }
+
+    RunnerHost host(runner);
+    if (!QDBusConnection::sessionBus().registerObject(QStringLiteral("/runner"), &host, QDBusConnection::ExportAllSlots)
+        || !QDBusConnection::sessionBus().registerService(arguments.at(2))) {
+        qWarning() << "Could not register" << arguments.at(2) << "on the session bus";
+        return 1;
+    }
+
+    return app.exec();
+}
